"""Eight-page academic report from verified experiment summaries and figures."""
import csv,json
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER,TA_JUSTIFY
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports/final';W=A4[0]-100;STORY=[]
styles={
 'body':ParagraphStyle('body',fontName='Times-Roman',fontSize=10.2,leading=12.6,spaceAfter=6,alignment=TA_JUSTIFY),
 'small':ParagraphStyle('small',fontName='Times-Roman',fontSize=8.6,leading=10.4,spaceAfter=5),
 'caption':ParagraphStyle('caption',fontName='Times-Roman',fontSize=8.8,leading=10.6,spaceAfter=8),
 'title':ParagraphStyle('title',fontName='Times-Bold',fontSize=18.5,leading=22,spaceAfter=10,alignment=TA_CENTER),
 'authors':ParagraphStyle('authors',fontName='Times-Roman',fontSize=10,leading=13,spaceAfter=10,alignment=TA_CENTER),
 'heading':ParagraphStyle('heading',fontName='Times-Bold',fontSize=12.3,leading=15,spaceBefore=6,spaceAfter=7),
 'sub':ParagraphStyle('sub',fontName='Times-Bold',fontSize=10.6,leading=13,spaceBefore=5,spaceAfter=5)}
def p(text,style='body'):STORY.append(Paragraph(text,styles[style]))
def h(text):p(text,'heading')
def sub(text):p(text,'sub')
def page():STORY.append(PageBreak())
def load(name):return json.loads((ROOT/name).read_text())
def figure(name,caption,width=W):
 from PIL import Image as PILImage
 path=OUT/'figures'/name
 with PILImage.open(path) as im:iw,ih=im.size
 STORY.append(Image(str(path),width=width,height=width*ih/iw));p(caption,'caption')
def table(rows,widths):
 data=[[Paragraph(escape(str(v)).replace('\n','<br/>'),styles['small']) for v in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eeeeee')),('LINEABOVE',(0,0),(-1,0),.7,colors.black),('LINEBELOW',(0,0),(-1,0),.5,colors.black),('LINEBELOW',(0,-1),(-1,-1),.7,colors.black),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
 STORY.append(t);STORY.append(Spacer(1,7))
def footer(canvas,doc):
 canvas.setFont('Times-Roman',8);canvas.drawString(50,27,'CS6048 | Group 4 | LEO-aware live video streaming');canvas.drawRightString(A4[0]-50,27,str(doc.page))

def main():
 project=load('configs/final/project.json');joint=load('artifacts/final/evaluation/four-policy-analysis.json');full=load('artifacts/final/evaluation/analysis.json');cal=load('artifacts/final/calibration/comparison.json')
 assert joint['sessions']==80 and full['sessions']==179
 a={r['policy']:r for r in joint['overall']};labels={'original':'Original CMAB','improved':'Improved CMAB','conventional':'Conventional A2C','leo':'LEO-aware A2C'}
 contributions=list(csv.DictReader((OUT/'tables/T6-contributions-template.csv').open()))
 assert len(contributions)==3
 by_roll={r['roll']:r['specific_completed_work_2_to_3_sentences'].strip() for r in contributions}
 p('LEO-Aware Live Video Streaming:<br/>RL-Based Adaptive Bitrate Selection','title')
 p('Anjan R D (ME23B157) &nbsp; | &nbsp; Rajat Dugar (ME23B114)<br/>Deviprasad V K (ME23B164)<br/>Group 4 | CS6048: Modern Networking Methods (Beyond TCP &amp; IP)<br/>Final course project report, November 2026','authors')
 sub('Abstract')
 p('We investigate whether replacing the supplied Starlink live-streaming artifact\'s contextual multi-armed bandit (CMAB) improves playback while preserving the remaining testbed. We study restart exploration, feedback attribution, context scaling and safety constraints, and train two compatible advantage actor-critic (A2C) policies from fresh networks. A balanced comparison uses 80 actual Chrome sessions: four policies, ten fixed scenarios and two matched repeats. Mean common QoE per wall second is -1.077 for original CMAB, 0.215 for improved CMAB, 0.239 for conventional A2C and 0.240 for LEO-aware A2C. Corresponding mean rebuffering is 49.75, 16.99, 9.55 and 9.14 seconds per 120-second session. All three developed controllers improve aggregate QoE relative to the original on this suite, but direct intervals among them include zero; adding LEO observations does not establish a further gain. Supporting ablations, calibration and 179 total frozen browser sessions expose regressions, guard-only competitiveness and simulator limitations. The release includes synchronous browser inference, portable event evidence and scripts that recompute results without MongoDB.')
 h('1. Problem statement and related work')
 p('Our objective is a better adaptive bitrate (ABR) controller for low-latency LEO-network playback, compared with the reference CMAB, under the same media, network schedule and playback controls. We change the policy and its causal observation/feedback interface; optional congestion-control work is excluded. Conditions combine measured round-trip time (RTT) with declared generated capacity and interruptions. Results concern this emulation suite, not a universal improvement on operational Starlink links.')
 p('The MMSys artifact [1,2] supplies a live DASH player and satellite-network emulator. Pensieve [3] motivates client-observation actor-critic control. Plume [4] studies workload representation and sampling for network RL; its Maguro/Gelato implementation [5] has an incompatible ten-action, metadata-rich interface. We train compatible actors using standard A2C [6]; we use balanced scenario families, not Plume\'s full clustering/prioritization framework. Our contribution is an audited controller refinement and a common deployed evaluation, not unchanged published weights or a novel A2C architecture.')
 sub('1.1 Team contribution statements')
 table([['Member','Roll number','Specific completed work (2-3 factual sentences)']]+[[m['name'],m['roll'],by_roll[m['roll']] or '________________________________________\n________________________________________\n________________________________________'] for m in project['members']],[94,73,W-167])

 page();h('2. Shared system and CMAB refinement')
 figure('F1-system.png','Figure 1. Common emulation and evidence paths. MongoDB stores measurements; synchronous decisions consume player state and cached, timestamped RTT health.')
 p('The inherited stack contains livesim2, an Nginx media proxy shaped by Linux tc/netem, Chrome/dash.js, an RTT/statistics sidecar and MongoDB. Eight video representations share 2-second full segments in a 60-second loop. Every policy uses a 3-second live target, LoL+ catch-up and a 0.83-1.17 playback-rate range. The team Docker build copies local dash.js; the original prebuilt image would ignore local edits. Trials record requested and actually played quality, so an inference call alone is not treated as improvement.')
 sub('2.1 Original controller and objective mismatch')
 p('Original CMAB fits MABWiser linear Thompson sampling (LinTS) in synchronous Pyodide/WebAssembly. Its three fitted features are throughput, playback rate and legacy RTT; buffer and explicit live delay are absent. At seconds 12, 27, 42 and 57, history clears and the next seven decision callbacks force the highest representation. Callbacks need not be seven distinct completed segments; this is aggressive exploration on impaired links.')
 p('Its internal reward is <i>O46 x (target delay/current delay) x (selected nominal bitrate/maximum bitrate) - selected-bitrate stall share</i>. The single-segment P.1203 call uses an empty stalling list and the new choice is scored before its request completes. These are limitations of this use and attribution of the reward, not of P.1203 itself. They can favor a high selected rate without establishing that its video was delivered and played.')
 sub('2.2 Validation-selected guarded CMAB')
 p('Improved CMAB keeps up to 30 matched completed outcomes, LinTS alpha 1 and seed 123456. Its nine fixed-scale coordinates are bias, throughput, playback rate, RTT, buffer, live delay, probe validity, last-success age and recent valid RTT change. A request consumes one matching decision and updates once using its original context. Errored, cancelled and unmatched requests are censored: attribution improves, but completed-request selection bias remains. A download-outcome surrogate penalizes starvation, variation and excess delay (Appendix A).')
 p('The first choice after each restart is conservative. A ceiling clips the proposed nominal rate to 0.55 times measured throughput when buffer &lt;1 second, delay &gt;target+2 seconds, or the probe is invalid; otherwise the factor is 0.85. Even the lowest rate may exceed capacity, so this is not a no-stall guarantee. Guard-only chooses the ceiling directly and also replaces restart choices; it tests a package, not a pure removal of learning.')

 page();h('3. Neural development and synchronous deployment')
 table([['Policy','Causal observation vector','Actor'],['Conventional A2C','8 completed-transfer rows x 4 values + buffer, previous rate, playback rate, target','36 -> 64 -> 64 -> 8'],['LEO-aware A2C','Conventional 36 + 8 RTT rows x 3 values + delay, success age, valid flag, failure fraction','64 -> 64 -> 64 -> 8']],[84,287,W-371])
 p('Transfer rows contain throughput/10 Mbps, HTTP time/2 seconds, age/30 seconds and presence. Globals use buffer/target, previous/max nominal rate, playback-rate offset/0.17 and target/6 seconds. Additional probe rows contain RTT/200 ms, age/4 seconds and success; remaining globals scale delay and success age by 3 seconds. Fixed clipping and padding are used. Only mature past probes and completed transfers are exposed: no future capacity, outage label, scenario identity or future SSIM is available. Playback rate can indirectly reflect delay, so the extension tests an observation bundle, not RTT alone.')
 p('We configured standard SB3 A2C with two 64-unit ReLU layers and eight actions; the value network is training-only. Both actors start as fresh networks. An 8,000-state causal throughput/buffer teacher initialization on training scenarios (10 epochs) precedes RL. Four learning-rate/rollout/entropy recipes, two screening seeds and 250k decisions per fit produce 16 fits (4.004 million interactions). One joint validation-selected recipe is used for five fresh seeds per actor at one million decisions each (10.004 million interactions). Main fitting took 44.33 minutes on the measured CPU configuration, selected after benchmarking against the tested GPU configuration.')
 p('The selected recipe uses learning rate 0.0001, rollout 64, entropy coefficient 0.02, gamma 0.99, GAE lambda 1, value coefficient 0.5, gradient clipping 0.5, normalized advantages and eight environments. Each run retains its best equal-family validation checkpoint. The predeclared median-validation seed represents each actor in Chrome: conventional 167 and LEO-aware 101. We retain five-seed curves and late deterioration; the final test does not select checkpoints or trigger training.')
 figure('F7-report-training.png','Figure 2. Validation means over five main seeds; bands are min-max ranges, not confidence intervals. Step zero follows teacher initialization. Earlier selected peaks are retained as later training declines.')
 sub('3.1 Export and equivalence checks')
 p('Actors export as executable JavaScript weights with Float32 dense/ReLU operations and deterministic argmax: 7,048 and 8,840 parameters. The browser receives an immediate action without a Promise or worker bridge; asynchronously refreshed RTT remains cached input. Across 394 native/JS fixtures, actions match and maximum logit error is 1.14 x 10<super>-5</super>. All final neural decisions are also replayed numerically from recorded browser inputs. This runtime blocks the main thread during inference; measured cost is small (Section 7), but is not a mobile-hardware guarantee.')

 page();h('4. Data, calibration and controlled methodology')
 sub('4.1 Trace sufficiency and separation')
 p('The supplied trace measures RTT for about one hour; it lacks synchronized capacity, confirmed handover labels and optimal actions. RTT alone is insufficient to train or fairly stress ABR. We retain measured timing and generate reproducible capacity, interruption and recovery schedules using seeded manifests. Seychelles windows are split into training 0-2088 seconds, validation 2148-2844 seconds and test 2904-3600 seconds, with 60-second guards. Neural preparation has 48/18/18 generated scenarios; the older simulator test set is not used for final selection.')
 p('Browser development and validation each use six cases. Final testing has ten cases from Seychelles and a second public LENS RTT session from Victoria. Five families cover steady bandwidth, capacity variation, RTT variation, interruption and recovery, with two cases each. An imposed interruption is not a confirmed satellite handover. Related windows and generated capacity are not independent measured full-link recordings.')
 sub('4.2 Quantified simulator limitations')
 p(f'Actual segment bytes, source availability, partial initial segments, 500 ms retry scheduling and catch-up seeks are modeled. Four fixed-policy development runs fit transport constants (capacity efficiency 0.9434, effective RTT multiplier 5.6, zero extra request overhead); outage-adjacent requests are excluded only from that fit. Adaptive cases do not fit it. Six development runs quantify calibration: median transfer error {100*cal["median_transfer_relative_error"]:.2f}%, buffer MAE {cal["buffer_mae_s"]:.3f} seconds and overall delay MAE {cal["latency_mae_s"]:.3f} seconds. The last misses the 1-second target; the overloaded no-playback case remains included. Playable-case delay MAE {cal["playable_cases_latency_mae_s"]:.3f} seconds is diagnostic, not an exclusion rule. TCP retransmission tails and exact browser seeking remain approximate. The simulator trains/screens; actual Chrome determines final results.')
 table([['Evidence block','Policies / matching','Sessions'],['Main joint comparison','4 policies x 10 cases x 2 matched repeats','80 (120 s)'],['Complete controlled matrix','7 policies x 10 x 2, plus third repeats for original / improved / guard-only CMAB','170 (120 s)'],['Repository raw replay','Original / improved / guard-only; 3 repeats each','9 (180 s)']],[130,290,W-420])
 sub('4.3 Controls, freezing and integrity')
 p('Policies run sequentially in balanced order with fresh state, matched source/reset phase and identical schedules. Dependencies preload before Load; setup time is recorded separately. Explicit hostClock=1 synchronizes this single-WSL-host emulator; original remote-clock defaults remain. Inventory, source/model hashes, case weights, repeats and selection are frozen before opening test performance. All 179 sessions pass compressed hashes, clock/cutoff consistency, recomputed metrics, applied shaping, actual input/action checks and unique feedback attribution. Algorithm-caused poor/no playback remains a result. The balanced 80-session view is post-measurement synthesis, not a newly untouched test; all original results are retained.')
 p('Supplementary raw replay follows the repository shaper: 20 Mbps, measured RTT, 1% normal loss and 100% loss for nonpositive trace values. These differ from the paper\'s 40 ms/0.1% normal and 100 ms/1% handover assumptions. We label it repository replay, not exact reproduction of paper settings.','small')

 page();h('5. Common QoE and four-policy results')
 p('<b>J = [Q - 4B - S - 0.3V - 0.1A] / T.</b> Q integrates log(nominal bitrate/300 kbps) over actually watched media seconds, divided by the 2-second segment duration. B is waiting after startup (events longer than 20 ms); S is startup seconds; V sums played-quality log changes; A integrates max(0,live delay-3 seconds) over wall time; T is actual observed wall duration, checked against the common requested horizon. Automatic catch-up waiting stays in B. Skipped video earns no watched-quality utility. A passive 100 ms ledger plus player events separates requests from playback. Mean and p95 delay are averaged per session; p95 is not a pooled-sample quantile.')
 p('The same independent score, coefficients, units and playback ledger apply to every policy, even though internal learning objectives differ. Nominal representation bitrate is a quality proxy, not MOS/SSIM/VMAF: for example the nominal 4.9 Mbps representation encodes at about 3.18 Mbps. Actual bytes drive delivery calculations. Equal family/case weighting prevents an algorithm\'s extra repeats from changing the main comparison.')
 rows=[['Policy','QoE/s','Stall s','Played\nMbps','Mean\ndelay s','p95\ndelay s']]
 for key in ['original','improved','conventional','leo']:
  r=a[key];rows.append([labels[key],f'{r["qoe_per_wall_s"]:.3f}',f'{r["stall_s"]:.2f}',f'{r["played_bitrate_bps"]/1e6:.2f}',f'{r["mean_live_latency_s"]:.2f}',f'{r["p95_live_latency_s"]:.2f}'])
 table(rows,[123,57,64,85,83,W-412])
 p('Table 1. Main balanced view: 20 sessions per policy, ten cases with two matched repeats, each 120 seconds. All three candidates reduce stalls and delay while selecting lower nominal quality.','caption')
 figure('F3-four-policy.png','Figure 3. Paired QoE changes against original CMAB. Points are the ten case means; diamonds and bars are the suite mean and conditional 95% paired-repeat interval.',width=440)
 rows=[['Candidate minus baseline','Mean difference','Conditional 95% interval']]
 for r in joint['pairs']:
  rows.append([labels[r['candidate']]+' - '+labels[r['baseline']],f'{r["mean_difference"]:+.4f}',f'[{r["ci95_low"]:+.4f}, {r["ci95_high"]:+.4f}]'])
 table(rows,[260,90,W-350])
 p('Table 2. All six direct contrasts on identical matched sessions. Intervals use 5,000 bootstrap draws of paired repeats within each fixed case. With two repeats and related traces they describe conditional repeatability, not population-wide Starlink uncertainty or multiplicity-adjusted superiority. Intervals among the three developed controllers include zero; the 0.0008 LEO-versus-conventional difference does not establish a LEO-input benefit.','caption')

 page();h('6. Mechanisms, tradeoffs and regressions')
 figure('F4-four-policy.png','Figure 4. Family-level changes from original CMAB, using the same two repeats for all four policies. Positive QoE and negative stall differences are favorable.')
 p('Gains concentrate where original CMAB\'s aggressive exploration conflicts with constrained delivery. The developed controllers trade nominal bitrate for less waiting and lower live delay. Neural actors are particularly conservative: about 1.23-1.25 Mbps played nominal bitrate, versus 2.97 Mbps for improved CMAB and 5.65 Mbps for the original. Original mean watched-media progression is 78.21 seconds, compared with 114.25, 116.06 and 116.84 seconds; catch-up skips fall from 38.00 seconds to 4.72, 3.12 and 2.33 seconds. Media progression may differ from wall time because playback rate varies.')
 figure('F5-four-policy-regression.png','Figure 5. All four policies on case test-handover_interruption-6131, repeat 0. This illustrates a previously identified regression case; repeat 0 is not its worst individual repeat. Played quality gaps represent unavailable/unplayed samples.')
 p('Improved CMAB has positive case-mean effects in 8/10 cases in the balanced view; the two steady cases regress because conservative quality loses utility without enough stall reduction. The complete three-repeat CMAB comparison has 7/10 gains: interruption case 6131 also regresses. Its improved/original scores are 0.795/0.726, 0.758/0.751 and 0.500/0.756 across repeats 0/1/2. Quality and variation costs outweigh lower stalls/delay in the three-repeat mean (-0.060 difference). We retain this repeat and show the underlying timeline rather than present only favorable episodes.')
 p('Neural smoothness and low stalling do not establish universally optimal quality. The common reward deliberately places substantial cost on stalls; coefficient choices and generated impairment severity affect rankings. All policies are scored identically, but their internal rewards are not numerically identical, and a higher final score is an empirical outcome rather than a guaranteed consequence of training.','small')

 page();h('7. Supporting studies and practical limits')
 table([['Hypothesis / change','Observed evidence and interpretation'],['H1 - longer memory','Memory alone did not consistently improve development playback.'],['H2 - restart exploration','Replacing seven highest-quality callbacks with a conservative restart helped.'],['H3 - delayed attribution','Original-reward delayed feedback was mixed; explicit request-outcome feedback was useful.'],['H4/H5 - context / scaling','Fixed physical scaling and bias avoid moving-scale/zero-centered degeneracy; context alone failed a useful-playback validation gate.'],['H6 - action ceiling','Guarded CMAB passed validation; guard-only remains competitive. A reseeded/refit variant was not promoted.']],[139,W-139])
 p('Table 3. Source-driven CMAB hypotheses and retained negative findings. Early development used external UTC setup and is exploratory, not a clean causal estimate for each individual edit. Corrected-clock validation used 24 sessions and unchanged playback/stall/delay/startup gates before final selection.','caption')
 p('Across the complete three-repeat CMAB suite, original/improved QoE is -1.081/0.190; paired improvement is +1.272 [1.227, 1.315] and mean stalls fall 64.87%. Guard-only scores 0.191; improved minus guard-only is -0.00095 [-0.0514, 0.0489]. Thus an incremental benefit of learning/restart over the guard package is not established. Native throughput (0.104) and BOLA (-0.084) are supporting references, each with two repeats. These complete-matrix numbers use different repeat counts from Table 1 and are not substituted into its joint comparison.')
 p('Six one-at-a-time sensitivity checks halve or double stall, variation and delay coefficients. Improved-minus-original remains positive (+0.734 to +2.347); this does not prove all policy rankings invariant. In the nine raw-replay sessions, scores are -4.406/-1.458/-1.261 for original/improved/guard-only. The original\'s roughly 4.3 seconds of played media per 180-second session is retained as a poor outcome, not filtered out.')
 sub('7.1 Measured runtime and deployment fidelity')
 deployment={r['policy']:r for r in load('artifacts/final/evaluation/deployment.json')['runs']}
 rows=[['Controller','Fresh calls','p50 ms','p95 ms','p99 ms','Max ms']]
 for key in ['improved','conventional','leo']:
  r=deployment[key];rows.append([labels[key],r['timed_fresh_decisions']]+[f'{r[k]:.2f}' for k in ['fresh_p50_ms','fresh_p95_ms','fresh_p99_ms','fresh_max_ms']])
 table(rows,[139,80,68,68,68,W-423])
 p('Table 4. Chrome 114 on the measured Linux/WSL laptop CPU, pooled descriptively across final sessions. CMAB measures controller selection only (outer feedback/rule work excluded); neural timing spans the deployed fresh decision. Original CMAB lacks comparable instrumentation, so no original-cost speedup is claimed. The 2,430 fresh neural calls had zero fallback; tests also checked invalid inputs, injected model failure and advancing fallback playback. Setup/prewarm cost is reported separately in deployment.json.','caption')
 sub('7.2 Limits and conclusion')
 p('Only RTT is measured; capacity and outage schedules are generated, and trace windows are related. Simulator live-delay error misses its target; two/three repeat intervals cannot support broad generalization. Nominal bitrate is a coarse quality proxy. Feedback censoring and approximate link dynamics remain. Five training seeds quantify simulator learning variability, but Chrome tests use one validation-selected representative per actor, not every seed. Within these limits, all three developed controllers improve aggregate playback QoE over original CMAB on a shared deployed suite. Safety and conservative quality explain much of the benefit; a distinct advantage for bandit learning or additional LEO observations is not demonstrated.')

 page();h('8. Reproducibility and source ownership')
 p('Repository: <link href="https://github.com/raj-gigt/mmsys24-starlink-livestreaming/tree/anjan" color="#174978">github.com/raj-gigt/mmsys24-starlink-livestreaming (branch anjan)</link>. The focused submission ZIP preserves required source paths, the complete measured player snapshot, final models, compact scenario arrays and raw event evidence for 179 final plus six calibration sessions. It omits environments, resume caches, redundant checkpoints, unrelated infrastructure and presentation material. Its explicit inventory and SHA-256 manifest distinguish inherited build/runtime files from developed algorithms, analyses and evidence; the full research history remains in the same Git repository.')
 table([['Purpose','Entry point / command'],['Results, no Docker/MongoDB','pip install -r requirements-results.txt\npython scripts/prepare_player.py\npython scripts/reproduce_final.py --saved-results'],['Actor numerical parity','node scripts/check_final_export.cjs'],['Training / export (separate ML requirements)','python -m rl.train_final --help\npython -m rl.export_final'],['Report (ReportLab academic layout)','pip install -r requirements-report.txt\npython scripts/build_final_report.py']],[145,W-145])
 p('The results command verifies all 303 frozen source files, two model identities, compressed raw hashes, actual applied schedules, observation/action replay and metric recomputation before regenerating analysis and plots. Read reports/final/reproduction.md for data regeneration, full browser reruns and hardware prerequisites. Live reruns require Docker/WSL and the pinned external media/dependency images; this package does not claim to be fully air-gapped. No new campaign is needed to inspect the submitted evidence.')
 p('Measured source publication: be131536f260d64a6c7e6e4478d51e01e60bcf62; dash.js pin: 60f56693032bb7e12c174951da4ee05818383527. Freeze SHA-256: c6e0730ba18c5515eabe05161594ade20d7f2a4e62ba127ef264aab71aaa1350. publication.json explains an older Git anchor in the freeze; the 303 individual canonical source hashes, not that anchor alone, identify the measured snapshot. Later packaging/report edits do not change those hashes.','small')
 sub('Appendix A. Internal surrogate and interface')
 p('Improved CMAB updates with r = log(b/300 kbps) x segment_s/2 - 4 max(0,transfer_s-buffer_at_choice) - 0.3 |log(b/previous_b)| - 0.1 max(0,outcome_delay-target) x transfer_s. This completed-request surrogate is separate from the independent final score. All actions map to nominal rates [0.30, 0.45, 0.90, 1.20, 1.50, 4.90, 5.10, 6.00] Mbps. Fixed normalization, ordering, masks, dimensions and weights are in models/final/*/{actor,manifest}.json and rl/features.py. rl/web implements synchronous inference; dash.js handles observations, routing and outcome matching. No model queries MongoDB during a bitrate decision.','small')
 sub('References')
 refs=[
 '[1] J. Zhao and J. Pan. Low-Latency Live Video Streaming over a Low-Earth-Orbit Satellite Network with DASH. ACM MMSys, 2024, pp. 109-120. DOI: 10.1145/3625468.3647616. Reference artifact: github.com/clarkzjw/mmsys24-starlink-livestreaming.',
 '[2] J. Zhao and J. Pan. LENS: A LEO Satellite Network Measurement Dataset. ACM MMSys, 2024, pp. 278-284. DOI: 10.1145/3625468.3652170. Data sources, licenses and hashes are in data/manifests.',
 '[3] H. Mao, R. Netravali and M. Alizadeh. Neural adaptive video streaming with Pensieve. ACM SIGCOMM, 2017. DOI: 10.1145/3098822.3098843.',
 '[4] S. Patel et al. Plume: A Framework for High Performance Deep RL Network Controllers via Prioritized Trace Sampling. arXiv:2302.12403, 2023. Published as Practically High Performant Neural Adaptive Video Streaming, Proc. ACM Netw., 2024. DOI: 10.1145/3696401.',
 '[5] S. Patel. Maguro/Gelato ABR reference implementation, github.com/sagar-pa/abr_rl_test, pinned b9c4069. Studied for adaptation; its published ten-action weights are not the deployed actors.',
 '[6] Stable-Baselines3, A2C documentation and implementation, version 2.9.2. stable-baselines3.readthedocs.io/en/master/modules/a2c.html. MABWiser 2.7.0 supplies LinTS in the inherited Python runtime.'
 ]
 for r in refs:p(escape(r),'small')
 p('Licensing: inherited parent GPL license and dash.js BSD notices are retained. Reference Maguro code is MIT; LENS data are CC BY-SA 4.0. The supplied Croatia media is credited to EBU/CTA (CC BY 4.0) in the original artifact; external media remain in the pinned source image.','small')
 doc=SimpleDocTemplate(str(OUT/'Group4-final-report.pdf'),pagesize=A4,leftMargin=50,rightMargin=50,topMargin=40,bottomMargin=45,title=project['submission_title'],author='Group 4: Anjan R D, Rajat Dugar, Deviprasad V K')
 doc.build(STORY,onFirstPage=footer,onLaterPages=footer)
 print(OUT/'Group4-final-report.pdf')

if __name__=='__main__':main()
